package br.com.pacto.recrutamento.core.entities;
import java.time.OffsetDateTime; import java.util.UUID;
public class RequisitoTemplateVaga { private UUID id=UUID.randomUUID(),templateVagaId; private String descricao; private boolean obrigatorio; private OffsetDateTime criadoEm,atualizadoEm,excluidoEm; public UUID getId(){return id;} public void setId(UUID x){id=x;} public UUID getTemplateVagaId(){return templateVagaId;} public void setTemplateVagaId(UUID x){templateVagaId=x;} public String getDescricao(){return descricao;} public void setDescricao(String x){descricao=x;} public boolean isObrigatorio(){return obrigatorio;} public void setObrigatorio(boolean x){obrigatorio=x;} public OffsetDateTime getCriadoEm(){return criadoEm;} public void setCriadoEm(OffsetDateTime x){criadoEm=x;} public OffsetDateTime getAtualizadoEm(){return atualizadoEm;} public void setAtualizadoEm(OffsetDateTime x){atualizadoEm=x;} public OffsetDateTime getExcluidoEm(){return excluidoEm;} public void setExcluidoEm(OffsetDateTime x){excluidoEm=x;} }
